insert into public.ce_course1_resources(id,data) values
('cannabis_pdf','{"base64": "", "sha256": "2e72b2ebdbb763d320a51709744459d0a3e6887bd5de3d0041d2b8bce18dd7d9", "filename": "CE_HALO_Cannabis_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('cannabis_questions','[{"module_id": "course_1_module_7", "question_id": "course_1_module_7_q01", "question_number": 1, "stem": "Which cannabis history is most useful before anesthesia?", "choice_a": "Product, route, amount, frequency, and exact time of last use", "choice_b": "Only whether use is legal in the patient''s state", "choice_c": "Only whether the patient calls it medical cannabis", "choice_d": "No history if a urine screen is negative", "correct_choice": "a", "rationale": "Universal, specific screening is more useful than legal-status counts or assumptions about a product.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [1], "source_ids": [1], "source_urls": ["https://rapm.bmj.com/content/early/2023/01/03/rapm-2022-104013"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q02", "question_number": 2, "stem": "Which cannabinoid is the principal psychoactive compound and drives most of the acute intoxication, cognitive impairment, and tachycardia associated with cannabis?", "choice_a": "Cannabinol (CBN)", "choice_b": "Tetrahydrocannabinol (THC)", "choice_c": "Cannabigerol (CBG)", "choice_d": "Cannabidiol (CBD)", "correct_choice": "b", "rationale": "THC is the principal psychoactive compound and is primarily responsible for intoxication, altered perception, impaired cognition, and tachycardia (Echeverria-Villalobos et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q03", "question_number": 3, "stem": "CBD is often perceived as therapeutically benign, but which anesthesia-relevant pharmacologic property makes it clinically important?", "choice_a": "CBD is an irreversible acetylcholinesterase inhibitor", "choice_b": "CBD is a potent MAO inhibitor", "choice_c": "CBD is pharmacologically active and may alter co-medication exposure through enzyme-mediated interactions", "choice_d": "CBD has no pharmacologic activity at any human receptor", "correct_choice": "c", "rationale": "Interaction magnitude depends on product, dose, and the co-medication. Review the exact drug rather than assuming all predicted interactions are equally established.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [1], "source_urls": ["https://rapm.bmj.com/content/early/2023/01/03/rapm-2022-104013"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q04", "question_number": 4, "stem": "CB1 receptors are BEST described as:", "choice_a": "Peripheral receptors concentrated only in the liver", "choice_b": "Immune-only receptors with no CNS relevance", "choice_c": "Enzymes rather than receptors", "choice_d": "Central nervous system receptors that modulate memory, mood, pain processing, appetite, and autonomic tone", "correct_choice": "d", "rationale": "CB1 receptors are concentrated in the CNS and modulate memory, mood, pain processing, appetite, and autonomic tone. Their activation is central to the anesthesia-relevant effects of THC (Cannabinoids and General Anesthetics review, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q05", "question_number": 5, "stem": "Which route of cannabis administration is MOST associated with delayed, unpredictable absorption and a longer duration of intoxication?", "choice_a": "Oral edibles", "choice_b": "Sublingual tincture", "choice_c": "Smoked flower", "choice_d": "Vaporized concentrate", "correct_choice": "a", "rationale": "Oral edibles have onset 30–120 minutes and duration 4–8 hours or more, with more unpredictable absorption than inhaled or sublingual routes (Echeverria-Villalobos et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q06", "question_number": 6, "stem": "A patient smoked cannabis 60 minutes before an elective outpatient procedure and now has HR 118, mild hypertension, and delayed responses. According to ASRA 2023 guidance, the MOST appropriate action is:", "choice_a": "Proceed as planned; there is no evidence-based reason to delay", "choice_b": "Postpone the elective surgery until the patient is clinically sober and able to participate in informed consent", "choice_c": "Give a benzodiazepine and proceed", "choice_d": "Cancel all future surgeries indefinitely", "correct_choice": "b", "rationale": "ASRA 2023 recommends postponing elective surgery in patients with altered mental status, impaired capacity, or acute intoxication related to cannabis. A 2-hour minimum after smoked cannabis is a floor, not a ceiling (Shah et al., 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q07", "question_number": 7, "stem": "What is the guideline-consistent MINIMUM delay recommended after smoked cannabis before proceeding with elective surgery?", "choice_a": "7 days", "choice_b": "24 hours", "choice_c": "2 hours", "choice_d": "30 minutes", "correct_choice": "c", "rationale": "ASRA-aligned guidance advises a minimum 2-hour delay after smoked cannabis before elective surgery because acute smoking increases heart rate, blood pressure, and airway irritation during a high-risk anesthesia window (Shah et al., 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q08", "question_number": 8, "stem": "Which of the following is the MOST accurate summary of postoperative pain expectations in chronic heavy cannabis users?", "choice_a": "Pain outcomes are identical regardless of cannabis use", "choice_b": "Cannabis eliminates postoperative pain entirely", "choice_c": "Chronic cannabis users reliably require less opioid than non-users", "choice_d": "Chronic cannabis users may have HIGHER postoperative pain scores and greater opioid requirements, so multimodal analgesia should be planned proactively", "correct_choice": "d", "rationale": "Contemporary reviews and observational data show chronic cannabis users may report higher postoperative pain scores and require MORE opioid — not less. Multimodal analgesia should be planned upfront (Preoperative Cannabinoid Exposure narrative review, 2026; Association of Cannabis Use After Discharge, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q09", "question_number": 9, "stem": "Which physiologic pattern is MOST characteristic of acute smoked cannabis exposure and relevant to induction planning?", "choice_a": "Tachycardia, hypertension, and airway irritation", "choice_b": "Bradycardia and hypotension", "choice_c": "Hypothermia and diaphoresis", "choice_d": "Hyperreflexia and clonus", "correct_choice": "a", "rationale": "Acute smoked cannabis characteristically produces tachycardia, hypertension, and airway irritation, which can complicate induction and increase perioperative cardiovascular risk (Alkhouli et al., 2025; APSF, 2026).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q10", "question_number": 10, "stem": "How should propofol dosing be approached in a habitual cannabis user?", "choice_a": "Automatically double the induction dose", "choice_b": "Titrate to effect; heterogeneous studies suggest higher average use but no fixed increment", "choice_c": "Assume chronic use eliminates respiratory depression", "choice_d": "Use the same fixed increase for every route and product", "correct_choice": "b", "rationale": "The 2025 review combined sedation and general-anesthesia data and does not establish a universal induction-dose rule.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [2], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q11", "question_number": 11, "stem": "Which airway concern is MOST relevant in chronic cannabis smokers or vapers during airway instrumentation?", "choice_a": "Guaranteed absence of airway reactivity", "choice_b": "Fixed upper-airway obstruction unrelated to inhaled products", "choice_c": "Airway hyperreactivity, bronchospasm, and increased secretions", "choice_d": "Complete loss of laryngeal reflexes", "correct_choice": "c", "rationale": "Inhaled cannabis can cause chronic cough, wheeze, sputum production, and airway hyperreactivity. Bronchospasm and increased secretions are reasonable perioperative concerns (APSF, 2026; Echeverria-Villalobos et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q12", "question_number": 12, "stem": "A patient reports classic cyclic vomiting relieved only by prolonged hot showers in the setting of daily cannabis use for five years. This history MOST strongly suggests:", "choice_a": "Routine postoperative nausea and vomiting", "choice_b": "Serotonin syndrome", "choice_c": "Acute appendicitis", "choice_d": "Cannabis hyperemesis syndrome (CHS)", "correct_choice": "d", "rationale": "The pattern supports CHS, but hot-water relief alone is not diagnostic. Assess alternative causes, hydration, and electrolytes.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [3], "source_urls": ["https://www.acep.org/toxicology/newsroom/april-2024/cannabinoid-hyperemesis-syndrome"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q13", "question_number": 13, "stem": "Which antiemetic strategy is MOST appropriate when a patient with cannabis hyperemesis syndrome does not respond to ondansetron?", "choice_a": "Consider alternative agents such as haloperidol or topical capsaicin, along with fluid and electrolyte support", "choice_b": "Add another 5-HT3 antagonist and hope for the best", "choice_c": "Administer a large opioid dose", "choice_d": "Withhold all antiemetics", "correct_choice": "a", "rationale": "Refractory CHS may require alternatives plus fluid/electrolyte treatment. Assess QT and other adverse-effect risks for the selected agent. Cannabis cessation is central to definitive management.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [5], "source_ids": [3], "source_urls": ["https://www.acep.org/toxicology/newsroom/april-2024/cannabinoid-hyperemesis-syndrome"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q14", "question_number": 14, "stem": "An adult presents intoxicated and confused before an elective procedure. Regarding informed consent, the MOST accurate statement is:", "choice_a": "Family members can always consent on behalf of an alert but intoxicated adult", "choice_b": "Acute cannabis intoxication may impair decision-making capacity, so elective surgery should be postponed until the patient can meaningfully participate in consent", "choice_c": "Documentation of intoxication is unnecessary", "choice_d": "Acute intoxication has no bearing on consent", "correct_choice": "b", "rationale": "Acute cannabis intoxication may impair attention, judgment, and the ability to understand information — undermining valid informed consent. Elective procedures should be postponed until the patient is clinically sober (Shah et al., 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q15", "question_number": 15, "stem": "A daily heavy cannabis user abruptly stops using 24 hours before surgery. Which withdrawal features should the CRNA anticipate perioperatively?", "choice_a": "Guaranteed seizures", "choice_b": "Complete asymptomatic withdrawal in all patients", "choice_c": "Irritability, anxiety, sleep disturbance, nausea, and restlessness", "choice_d": "Fixed dilated pupils and hyperthermia", "correct_choice": "c", "rationale": "Abrupt cannabis cessation in heavy users can cause irritability, anxiety, sleep disturbance, nausea, and restlessness beginning 1–2 days after cessation and lasting up to 2 weeks (Cleveland Clinic, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q16", "question_number": 16, "stem": "Which of the following is MOST consistent with the ASRA 2023 approach to cannabis screening in the preoperative interview?", "choice_a": "Skip cannabis entirely if the patient does not volunteer it", "choice_b": "Rely on routine urine toxicology in all patients", "choice_c": "Ask only patients who ''look like they use cannabis''", "choice_d": "Universal specific screening of every patient — product, route, frequency, and time of last use", "correct_choice": "d", "rationale": "ASRA 2023 recommends universal, specific screening — not selective questioning based on appearance. Routine toxicology is not recommended for all patients, but evaluation for acute intoxication is essential (Shah et al., 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q17", "question_number": 17, "stem": "A patient is scheduled for an urgent hip fixation and smoked cannabis 3 hours ago. The MOST appropriate action is to:", "choice_a": "Treat the patient according to current physiologic risk rather than delaying for cannabis exposure alone", "choice_b": "Refuse to provide anesthesia care", "choice_c": "Demand a several-week cannabis-free period before any care", "choice_d": "Cancel the case indefinitely", "correct_choice": "a", "rationale": "For urgent or emergent cases, the algorithm supports proceeding based on current physiologic risk rather than delaying solely because of recent cannabis exposure. Document capacity considerations if intoxication is present (Shah et al., 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q18", "question_number": 18, "stem": "Which of the following BEST describes contemporary evidence on cannabis and cardiovascular risk relevant to perioperative planning?", "choice_a": "Only smoked forms have any physiologic effects at all", "choice_b": "Cannabis use is associated with elevated risk of myocardial infarction and adverse cardiovascular events, particularly in younger adults and heavier users", "choice_c": "Cannabis is now considered cardioprotective at any dose", "choice_d": "Cannabis has no cardiovascular effects", "correct_choice": "b", "rationale": "Large-scale 2025 analyses continue to link cannabis with elevated MI and adverse cardiovascular event risk, especially in younger adults and heavier users (Alkhouli et al., 2025; ACC, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q19", "question_number": 19, "stem": "Regarding preoperative counseling of a patient using medical cannabis for chronic pain, the MOST appropriate approach is to:", "choice_a": "Ignore the medical context entirely", "choice_b": "Apply a rigid multi-week stop rule to every medical cannabis user", "choice_c": "Individualize the plan by clarifying indication, product, and consequences of abrupt cessation such as worsened pain, nausea, anxiety, or sleep", "choice_d": "Refuse to care for any medical cannabis patient", "correct_choice": "c", "rationale": "Medical cannabis users should be counseled individually. The goal is safer timing, honest disclosure, and individualized planning — not a punitive universal stop rule (Shah et al., 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q20", "question_number": 20, "stem": "Which combination is MOST important to warn patients against in the immediate postoperative recovery period?", "choice_a": "Cannabis combined with plain water", "choice_b": "Cannabis combined with acetaminophen", "choice_c": "Cannabis combined with topical antibiotics", "choice_d": "Cannabis combined with prescribed opioids, benzodiazepines, sleep aids, muscle relaxants, or alcohol", "correct_choice": "d", "rationale": "Patients should be advised not to combine cannabis with opioids, benzodiazepines, sleep aids, muscle relaxants, or alcohol during recovery — the combination increases drowsiness, dizziness, falls, and impaired recognition of complications (APSF, 2026).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q21", "question_number": 21, "stem": "Which recovery-period symptom pattern in a chronic cannabis user should MOST prompt evaluation for cannabis withdrawal rather than routine emergence issues?", "choice_a": "Irritability, anxiety, sleep disturbance, and nausea emerging 24–48 hours after abrupt cessation", "choice_b": "Isolated shoulder pain unrelated to procedure", "choice_c": "Rapid resolution of all symptoms without intervention", "choice_d": "Isolated postoperative pruritus", "correct_choice": "a", "rationale": "Cannabis withdrawal typically emerges within 1–2 days of cessation and features irritability, anxiety, sleep disturbance, nausea, and restlessness (Cleveland Clinic, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q22", "question_number": 22, "stem": "Which of the following BEST reflects contemporary guidance on universal preoperative cannabis abstinence duration?", "choice_a": "Cannabis must be held for at least 6 months before any elective procedure", "choice_b": "Current evidence does not support a single universal long-term hold; the focus is on avoiding surgery during acute intoxication and immediate physiologic effects", "choice_c": "A universal 30-day cessation period is mandated for every patient", "choice_d": "No cessation is ever recommended", "correct_choice": "b", "rationale": "Contemporary guidance does not support a universal long-term hold. The focus is on avoiding elective surgery during acute intoxication and immediate physiologic effects (Shah et al., 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q23", "question_number": 23, "stem": "A CBD-heavy medical cannabis user is scheduled for surgery on multiple medications including a direct oral anticoagulant and an antiepileptic. The MOST anesthesia-relevant drug-interaction concern is:", "choice_a": "CBD reliably decreases exposure of all co-administered drugs", "choice_b": "CBD has no pharmacokinetic interactions", "choice_c": "CBD-mediated CYP450 inhibition may alter exposure of co-administered drugs including some antiepileptics and anticoagulants", "choice_d": "CBD is only relevant for topical medications", "correct_choice": "c", "rationale": "Review each interaction and evidence level. Do not abruptly stop prescribed cannabinoid antiepileptic therapy; coordinate the plan with the prescriber.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [1], "source_urls": ["https://rapm.bmj.com/content/early/2023/01/03/rapm-2022-104013"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q24", "question_number": 24, "stem": "Which single sentence BEST summarizes the CRNA''s practical role with perioperative cannabis?", "choice_a": "Ignore cannabis exposure — it is not anesthesia-relevant", "choice_b": "Refuse to care for any cannabis user", "choice_c": "Apply a universal 30-day stop rule to every patient", "choice_d": "Screen universally with product-level detail, postpone elective surgery for acute intoxication, plan multimodal analgesia, and individualize care", "correct_choice": "d", "rationale": "Universal specific screening, postponing elective surgery for intoxication, proactive multimodal analgesia, and individualized care form the ASRA-aligned CRNA approach to perioperative cannabis (Shah et al., 2023; APSF, 2026).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_7", "question_id": "course_1_module_7_q25", "question_number": 25, "stem": "A patient scheduled for elective ambulatory surgery admits to smoking cannabis 90 minutes before arrival, denies intoxication, but has HR 112 and mild hypertension. Which of the following BEST reflects the ASRA-consistent decision pathway?", "choice_a": "Delay at least until the 2-hour post-smoke floor has passed and physiologic signs have normalized; extend the delay if tachycardia or hypertension persist", "choice_b": "Sedate the patient heavily until symptoms disappear and proceed", "choice_c": "Cancel indefinitely and refuse future care", "choice_d": "Proceed immediately regardless of hemodynamics", "correct_choice": "a", "rationale": "A minimum 2-hour delay after smoked cannabis is guideline-consistent, but persistent tachycardia or hypertension warrants further delay. The 2-hour floor is not a ceiling (Shah et al., 2023; APSF, 2026).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.jacc.org/doi/10.1016/j.jacadv.2025.101698", "https://www.acc.org/latest-in-cardiology/journal-scans/2025/03/24/13/52/cannabis", "https://my.clevelandclinic.org/health/diseases/marijuana-weed-withdrawal", "https://www.congress.gov/crs-product/IF12270", "https://doi.org/10.3389/fphar.2024.1282831", "https://journals.lww.com/anesthesia-", "https://emcrit.org/ibcc/cannabis/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11867069/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11818839/", "https://www.ncsl.org/health/state-medical-cannabis-laws", "https://pubmed.ncbi.nlm.nih.gov/41406677/", "https://pubmed.ncbi.nlm.nih.gov/38771607/", "https://pubmed.ncbi.nlm.nih.gov/36596580/", "https://pubmed.ncbi.nlm.nih.gov/37638417/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12063680/"], "source_provenance": "provider_submitted_content_and_reference_list"}]'::jsonb)
